select
 (select md5(string_agg(concat_ws('|',m.slug,m.model_year,m.name,m.generation,m.assembly_plant,m.basic_warranty,m.powertrain_warranty,m.roadside_assistance), ';' order by m.slug)) from models m join brands b on b.id=m.brand_id where b.slug='acura') models,
 (select md5(string_agg(concat_ws('|',m.slug,t.name,t.slug,t.msrp_usd,t.build_url,t.build_url_level,t.destination_usd), ';' order by m.slug,t.slug)) from trims t join models m on m.id=t.model_id join brands b on b.id=m.brand_id where b.slug='acura') trims,
 (select md5(string_agg(concat_ws('|',m.slug,o.category,o.name,o.price_usd,o.install_hours,o.manufacturer_code,o.parts_note,o.source_url), ';' order by m.slug,o.manufacturer_code)) from options o join models m on m.id=o.model_id join brands b on b.id=m.brand_id where b.slug='acura') options,
 (select md5(string_agg(concat_ws('|',m.slug,t.slug,o.manufacturer_code), ';' order by m.slug,t.slug,o.manufacturer_code)) from trim_options x join options o on o.id=x.option_id join trims t on t.id=x.trim_id join models m on m.id=o.model_id join brands b on b.id=m.brand_id where b.slug='acura') option_links,
 (select md5(string_agg(concat_ws('|',m.slug,o.manufacturer_code,r.rule,o2.manufacturer_code), ';' order by m.slug,o.manufacturer_code,r.rule,o2.manufacturer_code)) from option_rules r join options o on o.id=r.option_id join options o2 on o2.id=r.other_option_id join models m on m.id=o.model_id join brands b on b.id=m.brand_id where b.slug='acura') rules,
 (select md5(string_agg(concat_ws('|',m.slug,p.name,p.manufacturer_code,p.price_usd,t.slug,array_to_string(tp.interior_colors,'/')), ';' order by m.slug,p.name,t.slug)) from trim_paints tp join paints p on p.id=tp.paint_id join trims t on t.id=tp.trim_id join models m on m.id=p.model_id join brands b on b.id=m.brand_id where b.slug='acura') paints,
 (select md5(string_agg(concat_ws('|',m.slug,t.slug,horsepower,torque_lb_ft,zero_to_sixty_s,mpg_city,mpg_highway,mpg_combined,engine,engine_aspiration,transmission,drivetrain,seating,cargo_cu_ft,towing_lb,powertrain_type,nhtsa_overall_stars,epa_annual_fuel_cost_usd,s.source_url), ';' order by m.slug,t.slug)) from trim_specs s join trims t on t.id=s.trim_id join models m on m.id=t.model_id join brands b on b.id=m.brand_id where b.slug='acura') specs,
 (select count(*) from trim_specs s join trims t on t.id=s.trim_id join models m on m.id=t.model_id join brands b on b.id=m.brand_id where b.slug='acura') spec_rows;
